/bin/bash -c "python3 - <<'PY'
from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
urls=set()
for p in r.pages:
    for a in p.get('/Annots', []):
        obj=a.get_object()
        act=obj.get('/A')
        if act:
            uri=act.get_object().get('/URI')
            if uri: urls.add(str(uri))
print('\\n'.join(sorted(urls)) if urls else 'No external URL annotations found.')
PY"
